from enum import Enum


class AuthorizationOutcome(Enum):
    """What the payment provider decided about one authorization request."""

    DECLINED = "declined"
    APPROVED = "approved"
from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class Money:
    """An amount and the currency it is expressed in."""

    amount: Decimal
    currency: str

    def __post_init__(self) -> None:
        if self.amount <= 0:
            raise ValueError("An amount must be positive.")
        if not self.currency or not self.currency.strip():
            raise ValueError("A currency is required.")
        object.__setattr__(self, "currency", self.currency.upper())
from typing import final

from payment.application.payment_gateway import PaymentGateway
from payment.application.receipt_store import ReceiptStore
from payment.domain.authorization_outcome import AuthorizationOutcome
from payment.domain.money import Money


@final
class AuthorizePayment:
    """Authorizes one payment and keeps a receipt of what the provider answered."""

    def __init__(self, gateway: PaymentGateway, receipts: ReceiptStore) -> None:
        self._gateway = gateway
        self._receipts = receipts

    def handle(self, reference: str, amount: Money) -> AuthorizationOutcome:
        outcome = self._gateway.authorize(reference, amount)
        self._receipts.save(reference, f"{amount.currency} {amount.amount} -> {outcome.name}")
        return outcome
from typing import Protocol

from payment.domain.authorization_outcome import AuthorizationOutcome
from payment.domain.money import Money


class PaymentGateway(Protocol):
    """Outbound gateway to the payment provider."""

    def authorize(self, reference: str, amount: Money) -> AuthorizationOutcome: ...
from typing import Protocol


class ReceiptStore(Protocol):
    """Outbound store keeping one receipt per authorization attempt."""

    def save(self, reference: str, body: str) -> None: ...
from decimal import Decimal

from payment.application.authorize_payment import AuthorizePayment
from payment.domain.authorization_outcome import AuthorizationOutcome
from payment.domain.money import Money


class AlwaysAnswers:
    def __init__(self, outcome: AuthorizationOutcome) -> None:
        self._outcome = outcome

    def authorize(self, reference: str, amount: Money) -> AuthorizationOutcome:
        return self._outcome


class InMemoryReceiptStore:
    def __init__(self) -> None:
        self.saved: dict[str, str] = {}

    def save(self, reference: str, body: str) -> None:
        self.saved[reference] = body


def test_an_approved_payment_is_reported_as_approved() -> None:
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.APPROVED), InMemoryReceiptStore())

    outcome = handler.handle("ORD-1", Money(Decimal("42.50"), "eur"))

    assert outcome is AuthorizationOutcome.APPROVED


def test_every_attempt_leaves_a_receipt_behind() -> None:
    receipts = InMemoryReceiptStore()
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.DECLINED), receipts)

    handler.handle("ORD-2", Money(Decimal("10"), "EUR"))

    assert "ORD-2" in receipts.saved
