from dataclasses import FrozenInstanceError
from decimal import Decimal

import pytest

from payment.domain.money import Money


def test_a_currency_is_normalised_to_upper_case() -> None:
    assert Money(Decimal("5"), "eur").currency == "EUR"


@pytest.mark.parametrize("amount", ["0", "-0.01", "-1"])
def test_a_non_positive_amount_is_rejected(amount: str) -> None:
    with pytest.raises(ValueError, match="positive"):
        Money(Decimal(amount), "EUR")


@pytest.mark.parametrize("amount", ["0.01", "0.5", "1"])
def test_a_small_positive_amount_is_accepted(amount: str) -> None:
    assert Money(Decimal(amount), "EUR").amount == Decimal(amount)


